import smbus, time

ADS1015 = 0x00
ADS1115 = 0x01

def swap(x):
    return ((x & 0xff00) >> 8) | ((x & 0x00ff) << 8)

class ADC:
    def __init__(self, t=ADS1015, bus=1, addr=0x48):
        self.t = t
        self.bus = smbus.SMBus(bus)
        self.addr = addr

    def read(self, c):
        if self.t == ADS1015:
            cmd = 0x01 | 0x80 | (c << 4)
        else:
            cmd = 0x01 | 0x83 | (c << 4)
        self.bus.write_i2c_block_data(self.addr, 0x01, [cmd, 0x00])
        time.sleep(0.05)
        d = self.bus.read_i2c_block_data(self.addr, 0x00, 2)
        return swap(d[0] | (d[1] << 8))

if __name__ == "__main__":
    adc = ADC()
    try:
        while True:
            for c in range(4):
                v = adc.read(c)
                print(f"Channel {c}: {v}")
            time.sleep(0.05)
    except KeyboardInterrupt:
        pass

