    try:
        return adafruit_max30102.MAX30102(i2c_bus)
    except Exception as e:
        print(f"Error initializing sensor: {e}")
        return None

def read_sensor_data(sensor):
    """Read raw IR and RED ADC values from the sensor."""
    try:
        return sensor.spo2, sensor.ir
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return None, None

def process_sensor_data(spo2, ir):
    """Process the sensor data to estimate heart rate."""
    if spo2 is None or ir is None:
        return None

    # Approximate heart rate based on SpO2 (adjust as needed for your specific sensor)
    heart_rate = spo2  # Placeholder: Replace with a more sophisticated algorithm if needed
    return heart_rate

def log_heart_rate(heart_rate, log_file):
    """Log the heart rate with a timestamp to a file."""
    timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
    log_entry = f"{timestamp} - Heart Rate: {heart_rate} bpm\n"
    try:
        with open(log_file, "a") as file:
            file.write(log_entry)
    except Exception as e:
        print(f"Error writing to log file: {e}")

def print_heart_rate(heart_rate):
    """Print the heart rate to the console."""
    print(f"Heart Rate: {heart_rate} bpm")

def main():
    """Main function to read and process heart rate data."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    sensor = initialize_sensor(i2c_bus)
    if sensor is None:
        return

    heart_rate_window = []

    try:
        while True:
            spo2, ir = read_sensor_data(sensor)
            heart_rate = process_sensor_data(spo2, ir)

            if heart_rate is not None:
                heart_rate_window.append(heart_rate)
                if len(heart_rate_window) > 10:
                    heart_rate_window.pop(0)  # Maintain a rolling window of 10 readings

                # Calculate the average heart rate over the window
                avg_heart_rate = sum(heart_rate_window) / len(heart_rate_window) if heart_rate_window else None

                log_heart_rate(avg_heart_rate, LOG_FILE)
                print_heart_rate(avg_heart_rate)

            time.sleep(SLEEP_INTERVAL)

    except KeyboardInterrupt:
        print("Program terminated by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # No specific cleanup needed for I2C or the sensor object itself in this library,
        # but including a placeholder for potential future needs.
        print("Exiting program.")

if __name__ == "__main__":
    main()

