import time
import logging
from picamera2 import Picamera2
from pyzbar.pyzbar import decode

# Configure logging for debugging and error tracking
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

def initialize_camera():
    """Initializes the Raspberry Pi camera module."""
    try:
        camera = Picamera2()
        camera.configure(camera.create_preview_configuration(main={"format": 'XRGB8888', "size": (64, 64)}))
        camera.start()
        logging.info("Camera initialized successfully.")
        return camera
    except Exception as e:
        logging.error(f"Error initializing camera: {e}")
        return None

def capture_frame(camera):
    """Captures a single frame from the camera."""
    try:
        frame = camera.capture_array()
        logging.info("Frame captured successfully.")
        return frame
    except Exception as e:
        logging.error(f"Error capturing frame: {e}")
        return None

def decode_qr_code(frame):
    """Decodes QR codes from a frame using pyzbar."""
    try:
        decoded_objects = decode(frame)
        logging.info("QR code decoded successfully.")
        return decoded_objects
    except Exception as e:
        logging.error(f"Error decoding QR code: {e}")
        return None

def process_qr_code(decoded_objects):
    """Processes decoded QR code data (placeholder for actual processing)."""
    if decoded_objects:
        for obj in decoded_objects:
            logging.info(f"Decoded QR code: {obj.data.decode('utf-8')}")

def main():
    """Main function to capture and decode QR codes."""
    camera = initialize_camera()
    if not camera:
        print("Failed to initialize camera. Exiting.")
        return

    frame = capture_frame(camera)
    if not frame:
        print("Failed to capture frame. Exiting.")
        camera.close()
        return

    decoded_objects = decode_qr_code(frame)
    if decoded_objects:
        process_qr_code(decoded_objects)
    else:
        print("No QR code detected.")

    camera.close()
    logging.info("Program finished.")

if __name__ == "__main__":
    main()

