import time
import numpy as np
import cv2

# Configuration constants
CAMERA_FRAMERATE = 15  # Frames per second
WARMUP_DELAY = 2  # Seconds to let the camera warm up
MOTION_THRESHOLD = 10  # Threshold for motion detection

def initialize_camera():
    """Initializes the camera and returns the capture object."""
    try:
        capture = cv2.VideoCapture(0, cv2.CAP_CSIDV1)  # Use CSI camera
        if not capture.isOpened():
            raise IOError("Cannot open camera")

        capture.set(cv2.CAP_PROP_FRAME_WIDTH, 640)  # Set resolution
        capture.set(cv2.CAP_PROP_FRAME_HEIGHT, 480)
        capture.set(cv2.CAP_PROP_FPS, CAMERA_FRAMERATE)
        time.sleep(WARMUP_DELAY)  # Warm-up period
        return capture
    except Exception as e:
        print(f"Error initializing camera: {e}")
        return None

def capture_frame(capture):
    """Captures a frame from the camera and returns it as a NumPy array."""
    ret, frame = capture.read()
    if not ret:
        print("Failed to capture frame")
        return None
    return frame

def calculate_average_color(frame):
    """Calculates the average color of a frame."""
    return np.mean(frame)

def detect_motion(current_average, baseline_average, threshold):
    """Detects motion based on the difference between average colors."""
    difference = np.abs(current_average - baseline_average)
    return difference > threshold

def save_image(frame, filename="motion.jpg"):
    """Saves a frame as an image file."""
    try:
        cv2.imwrite(filename, frame)
        print(f"Image saved as {filename}")
    except Exception as e:
        print(f"Error saving image: {e}")


def main():
    """Main function to run the motion detection system."""
    capture = initialize_camera()
    if capture is None:
        return

    baseline_average = None

    try:
        while True:
            frame = capture_frame(capture)
            if frame is None:
                continue

            current_average = calculate_average_color(frame)

            if baseline_average is None:
                baseline_average = current_average
                continue

            if detect_motion(current_average, baseline_average, MOTION_THRESHOLD):
                print("Motion detected!")
                save_image(frame)
                baseline_average = current_average

            time.sleep(2)  # Pause for 2 seconds

    except KeyboardInterrupt:
        print("Program terminated by user.")
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        capture.release()
        cv2.destroyAllWindows()
        print("Camera released and windows closed.")

if __name__ == "__main__":
    main()

