import RPi.GPIO as GPIO
import time
import signal
import sys

# Define GPIO pins using BCM numbering
KEY_PAD_KEYS = [4, 5, 6]
KEY_PAD_OUTPUTS = [23, 24]

# Define a dictionary to store the state of each key
key_state = {key: False for key in KEY_PAD_KEYS}

# Define a dictionary to store the state of each output
output_state = {output: False for output in KEY_PAD_OUTPUTS}

# Define a function to handle key press events
def handle_key_press(channel):
    """Handles a key press event."""
    try:
        if channel == KEY_PAD_KEYS[0]:
            key_state[KEY_PAD_KEYS[0]] = True
            output_state[KEY_PAD_OUTPUTS[0]] = True
            print("Key 1 pressed")
        elif channel == KEY_PAD_KEYS[1]:
            key_state[KEY_PAD_KEYS[1]] = True
            output_state[KEY_PAD_OUTPUTS[0]] = False
            print("Key 2 pressed")
        elif channel == KEY_PAD_KEYS[2]:
            key_state[KEY_PAD_KEYS[2]] = True
            output_state[KEY_PAD_OUTPUTS[1]] = not output_state[KEY_PAD_OUTPUTS[1]]
            print("Key 3 pressed")
    except Exception as e:
        print(f"Error handling key press: {e}")

# Define a function to handle key release events
def handle_key_release(channel):
    """Handles a key release event."""
    try:
        if channel == KEY_PAD_KEYS[0]:
            key_state[KEY_PAD_KEYS[0]] = False
        elif channel == KEY_PAD_KEYS[1]:
            key_state[KEY_PAD_KEYS[1]] = False
        elif channel == KEY_PAD_KEYS[2]:
            key_state[KEY_PAD_KEYS[2]] = False
    except Exception as e:
        print(f"Error handling key release: {e}")

# Define a function to set up GPIO pins
def setup_gpio():
    """Sets up the GPIO pins."""
    try:
        GPIO.setmode(GPIO.BCM)
        # Set up key pad keys as input with pull-up resistors
        for key in KEY_PAD_KEYS:
            GPIO.setup(key, GPIO.IN, pull_up_down=GPIO.PUD_UP)
            GPIO.add_event_detect(key, GPIO.FALLING, callback=handle_key_press)
            GPIO.add_event_detect(key, GPIO.RISING, callback=handle_key_release)
        # Set up key pad outputs
        for output in KEY_PAD_OUTPUTS:
            GPIO.setup(output, GPIO.OUT)
            GPIO.output(output, GPIO.LOW)
    except Exception as e:
        print(f"GPIO setup error: {e}")
        sys.exit(1)

# Define a function to clean up GPIO pins
def cleanup_gpio():
    """Cleans up the GPIO pins."""
    try:
        GPIO.cleanup()
    except Exception as e:
        print(f"GPIO cleanup error: {e}")

# Main function
def main():
    """Main function to run the key pad simulation."""
    setup_gpio()
    try:
        while True:
            time.sleep(0.05)
    except KeyboardInterrupt:
        print("Exiting program...")
    finally:
        cleanup_gpio()
        print("GPIO cleanup complete.")

if __name__ == "__main__":
    main()

