import cv2
import numpy as np
import time
from typing import List, Tuple

try:
    import RPi.GPIO as GPIO
    from smbus2 import SMBus
except ImportError:
    print("RPi.GPIO or smbus2 not found. Simulating LCD.")
    GPIO = None
    SMBus = None


def initialize_camera(camera_index: int = 0) -> cv2.VideoCapture:
    """Initializes the camera with error handling."""
    try:
        cap = cv2.VideoCapture(camera_index)
        if not cap.isOpened():
            raise IOError(f"Cannot open webcam {camera_index}")
        return cap
    except Exception as e:
        raise RuntimeError(f"Camera initialization failed: {e}")


def detect_and_predict_mask(image: np.ndarray, face_net: cv2.dnn_Net, mask_net: cv2.dnn_Net) -> Tuple[str, float, List[int]]:
    """Detects and predicts mask in an image using two neural networks."""
    try:
        (h, w) = image.shape[:2]
        blob = cv2.dnn.blobFromImage(image, 1.0, (224, 224), (104.0, 177.0, 123.0))
        face_net.setInput(blob)
        detections = face_net.forward()

        faces = []
        for i in range(0, detections.shape[2]):
            confidence = detections[0, 0, i, 2]
            if confidence > 0.1:
                box = detections[0, 0, i, 3:7] * np.array([w, h, w, h])
                (startX, startY, endX, endY) = box.astype("int")
                (startX, startY) = (max(0, startX), max(0, startY))
                (endX, endY) = (min(w - 1, endX), min(h - 1, endY))

                face = image[startY:endY, startX:endX]
                face_blob = cv2.dnn.blobFromImage(face, 1.0 / 255, (96, 96), (0, 0, 0), swapRB=True, crop=False)
                mask_net.setInput(face_blob)
                mask_confidence = mask_net.forward()[0, 0] * 100
                faces.append((mask_confidence, face))

        return ("Mask", 60.0) if len(faces) > 0 else ("No Mask", 0.0), 60.0 if len(faces) > 0 else 0.0, faces[0][1] if len(faces) > 0 else 0.0

    except Exception as e:
