import io
import numpy as np
import cv2

class CameraStreamBuffer:
    def __init__(self, c):
        self.c = c
        self.b = io.BytesIO()

    def write(self, d):
        if d.startswith(b'\xff\xd8'):
            self.c.write(self.b.getvalue())
            self.b = io.BytesIO()
        self.b.write(d)

class MotionDetectionBuffer:
    def __init__(self, f):
        self.f = f
        self.b = io.BytesIO()
        self.p = None

    def write(self, d):
        if d.startswith(b'\xff\xd8'):
            self.b.seek(0)
            self.p = self.decode_frame(self.b.read())
            self.b.seek(0)
            self.b.truncate()
        return self.b.write(d)

    def decode_frame(self, b):
        try:
            d = np.frombuffer(b, dtype=np.uint8)
            f = cv2.imdecode(d, cv2.IMREAD_COLOR)
            return f if f is not None else None
        except:
            return None

