import cv2
import pygame.mixer
import time
import sys
import os
import signal
import logging
import RPi.GPIO as GPIO

# Project‑specific modules
import config
import face
import sound

# Constants
SAMPLE_RATE = 48000
CHUNK_SIZE = 1024

# Logging configuration
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Global variables
mixer = None
camera = None
face_model = None
lock_pin = None

def initialize_resources():
    """Initializes all hardware and software resources."""
    global mixer, camera, face_model, lock_pin

    try:
        mixer = pygame.mixer.Init(48000, -16, 1, 1024)
        sound.load_sounds()
    except Exception as e:
        logger.error(f"Error initializing sound: {e}")
        sys.exit(1)

    try:
        camera = config.get_camera()
        face_model = cv2.face.EigenFaceRecognizer_create()
        face_model.read(config.TRAINING_FILE)
    except Exception as e:
        logger.error(f"Error initializing face recognition: {e}")
        sys.exit(1)

    try:
        lock_pin = config.get_lock_pin()
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(lock_pin, GPIO.OUT)
        GPIO.output(lock_pin, GPIO.HIGH)  # Lock initially locked
    except Exception as e:
        logger.error(f"Error initializing GPIO: {e}")
        sys.exit(1)


def unlock_door():
    """Unlocks the door."""
    try:
        GPIO.output(lock_pin, GPIO.LOW)
        logger.info("Door unlocked.")
    except Exception as e:
        logger.error(f"Error unlocking door: {e}")


def load_audio(path):
    """Loads audio data from the given path."""
    try:
        with open(path, 'rb') as f:
            return f.read()
    except FileNotFoundError:
        logger.error(f"Audio file not found: {path}")
        return None
    except Exception as e:
        logger.error(f"Error loading audio: {e}")
        return None


def process_audio(audio_data):
    """Processes audio data to detect commands."""
    try:
        sound.process_audio(audio_data)
    except Exception as e:
        logger.error(f"Error processing audio: {e}")


def main_loop():
    """Main program loop."""
    try:
        while True:
            try:
                audio_data = camera.get_audio_data(SAMPLE_RATE, CHUNK_SIZE)
                if audio_data is None:
                    continue

                process_audio(audio_data)
            except Exception as e:
                logger.error(f"Error in main loop: {e}")
                break  # Exit the loop on error

    except KeyboardInterrupt:
        logger.info("Program interrupted by user.")
    except Exception as e:
        logger.error(f"Unexpected error: {e}")
    finally:
        cleanup()


def cleanup():
    """Releases resources and performs cleanup."""
    try:
        if mixer:
            mixer.quit()
        if camera:
            camera.release()
        if face_model:
            face_model.release()
        if lock_pin:
            GPIO.cleanup()  # Important to cleanup GPIO pins
        logger.info("Resources cleaned up.")
    except Exception as e:
        logger.error(f"Error during cleanup: {e}")


def signal_handler(sig, frame):
    """Handles signals for graceful shutdown."""
    logger.info(f"Signal received: {sig}. Exiting gracefully...")
    cleanup()
    sys.exit(0)


if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    initialize_resources()

    try:
        while True:
            if camera.is_button_up():
                logger.info("Button pressed. Initiating face recognition...")
                try:
                    ret, image = camera.get_image()
                    if not ret:
                        logger.error("Error capturing image.")
                        continue

                    gray_image = cv2.cvtColor(image, cv2.COLOR_RGB2GRAY)
                    face_coords = face.detect_single(gray_image)

                    if face_coords is None:
                        logger.warning("No face detected.")
                        sound.play_sound("later")
                        continue

                    x, y, w, h = face_coords
                    cropped_face = face.crop(gray_image, x, y, w, h)
                    resized_face = face.resize(cropped_face)

                    label, confidence = face_model.predict(resized_face)

                    logger.info(f"Predicted label: {label}, Confidence: {confidence}")

                    if label == config.POSITIVE_LABEL and confidence < config.POSITIVE_THRESHOLD:
                        logger.info("Face recognized! Unlocking door...")
                        unlock_door()
                        sound.play_sound("welcome")
                    else:
                        logger.warning("Face not recognized.")
                        sound.play_sound("wait")
                except Exception as e:
                    logger.error(f"Error during face recognition: {e}")

            time.sleep(0.1)  # Reduced delay for responsiveness

    except Exception as e:
        logger.error(f"An unexpected error occurred: {e}")
    finally:
        cleanup()

