# Environmental Monitoring Station for Raspberry Pi Zero W
# Reads temperature, humidity, and light intensity from I2C sensors via a multiplexer

import time
import board
import busio
import adafruit_tca9548a
import adafruit_bme280
import adafruit_tsl2591

# Define sensor reading interval (seconds)
READ_INTERVAL = 2

def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return i2c_bus
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_multiplexer(i2c_bus):
    """Initialize the I2C multiplexer."""
    try:
        multiplexer_device = adafruit_tca9548a.TCA9548A(i2c_bus)
        return multiplexer_device
    except Exception as e:
        print(f"Error initializing multiplexer: {e}")
        return None

def initialize_sensors(multiplexer_device):
    """Initialize the connected sensors."""
    try:
        temperature_humidity_sensor = adafruit_bme280.Adafruit_BME280_I2C(multiplexer_device[0])
        light_sensor = adafruit_tsl2591.TSL2591(multiplexer_device[1])
        return temperature_humidity_sensor, light_sensor
    except Exception as e:
        print(f"Error initializing sensors: {e}")
        return None, None

def read_sensor_data(temperature_humidity_sensor, light_sensor):
    """Read temperature, humidity, and light intensity from the sensors."""
    try:
        temperature = temperature_humidity_sensor.temperature
        humidity = temperature_humidity_sensor.humidity
        light_intensity = light_sensor.lux
        return temperature, humidity, light_intensity
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return None, None, None

def display_sensor_data(temperature, humidity, light_intensity):
    """Display the sensor data in a user-friendly format."""
    if temperature is not None and humidity is not None and light_intensity is not None:
        print(f"Temperature: {temperature:.2f} C, Humidity: {humidity:.2f} %, Light: {light_intensity:.2f} lux")

def main():
    """Main function to read and display sensor data."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    multiplexer_device = initialize_multiplexer(i2c_bus)
    if multiplexer_device is None:
        return

    temperature_humidity_sensor, light_sensor = initialize_sensors(multiplexer_device)
    if temperature_humidity_sensor is None or light_sensor is None:
        return

