import serial
import time
import csv
import os
import logging
from functools import partial

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
SERIAL_PORT = "/dev/ttyACM0"
BAUD_RATE = 115200
TIMEOUT = 1
CSV_FILE = "temperature_log.csv"

def read_temperature_data(serial_port, baud_rate, timeout):
    """Reads temperature data from the serial port."""
    try:
        with serial.Serial(serial_port, baud_rate, timeout=timeout) as ser:
            data = ser.readline().decode('ascii', errors='replace').strip()
            return data
    except serial.SerialException as e:
        logging.error(f"Serial port error: {e}")
        return None

def process_temperature_data(data):
    """Processes the temperature data and converts it to Fahrenheit."""
    if not data:
        return None, None

    try:
        temperature_celsius = float(data)
        temperature_fahrenheit = (temperature_celsius * 9/5) + 32
        return temperature_celsius, temperature_fahrenheit
    except ValueError:
        logging.warning(f"Invalid data received: {data}")
        return None, None

def write_to_csv(filename, temperature_celsius, temperature_fahrenheit):
    """Writes the temperature data to the CSV file."""
    try:
        with open(filename, 'a', newline='') as csvfile:
            writer = csv.writer(csvfile)
            writer.writerow([time.strftime('%Y-%m-%d %H:%M:%S'), temperature_celsius, temperature_fahrenheit])
    except IOError as e:
        logging.error(f"File I/O error: {e}")

def main():
    """Main function to read, process, and log temperature data."""
    # Initialize CSV file with header if it doesn't exist
    if not os.path.exists(CSV_FILE) and not os.path.isfile(CSV_FILE):
        with open(CSV_FILE, 'w', newline='') as csvfile:
            writer = csv.writer(csvfile)
            writer.writerow(["Timestamp", "Temperature Celsius", "Temperature Fahrenheit"])

    read_from_serial = partial(read_temperature_data, SERIAL_PORT, BAUD_RATE, TIMEOUT)
    log_data = partial(write_to_csv, CSV_FILE)

    try:
        while True:
            data = read_from_serial()
            if data:
                temperature_celsius, temperature_fahrenheit = process_temperature_data(data)
                if temperature_celsius is not None and temperature_fahrenheit is not None:
                    logging.info(f"Temperature Celsius: {temperature_celsius:.2f}°C, Temperature Fahrenheit: {temperature_fahrenheit:.2f}°F")
                    log_data(temperature_celsius, temperature_fahrenheit)
            time.sleep(1)  # Reduced busy-waiting
    except KeyboardInterrupt:
        logging.info("Program terminated by user.")
    except Exception as e:
        logging.exception(f"An unexpected error occurred: {e}")

if __name__ == "__main__":
    main()

