import Adafruit_DHT
import RPi.GPIO as GPIO

# Sensor and pin configuration
DHT_SENSOR = Adafruit_DHT.DHT11
DHT_PIN = 4  # GPIO4 (physical pin 7)
API_ENDPOINT = 'http://127.0.0.1:5000/data'

def read_sensor_data():
    """Reads temperature and humidity from the DHT11 sensor."""
    humidity, temperature = Adafruit_DHT.read_retry(DHT_SENSOR, DHT_PIN)
    return temperature, humidity

def post_data(temperature, humidity):
    """Sends temperature and humidity data to the API endpoint."""
    payload = {'temperature': temperature, 'humidity': humidity}
    try:
        response = requests.post(API_ENDPOINT, json=payload)
        print(f'Data sent. Status code: {response.status_code}')
    except requests.exceptions.ConnectionError:
        print('Connection error. Data not sent.')

def main():
    """Main function to read sensor data and send it to the API."""
    try:
        while True:
            temperature, humidity = read_sensor_data()

            if temperature is not None and humidity is not None:
                print(f'Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%')
                post_data(temperature, humidity)
            else:
                print('Failed to retrieve data from sensor.')

            time.sleep(5)

    except KeyboardInterrupt:
        print('\nProgram stopped by user.')
    finally:
        GPIO.cleanup()  # Clean up GPIO on exit

if __name__ == "__main__":
    main()

