#!/usr/bin/env python3

"""
Reads temperature and humidity from an AHT20 sensor connected to a Raspberry Pi.
"""

import time
import board
import busio
import adafruit_ahtx0

# Constants
I2C_SCAN_INTERVAL = 5  # Seconds between I2C scan attempts
RETRY_DELAY = 5  # Seconds between sensor read retries

def initialize_i2c():
    """Initializes the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_sensor(i2c_bus):
    """Initializes the AHT20 sensor."""
    try:
        return adafruit_ahtx0.AHTx0(i2c_bus)
    except Exception as e:
        print(f"Error initializing sensor: {e}")
        return None

def read_sensor_data(sensor):
    """Reads temperature and humidity from the sensor."""
    try:
        temperature = sensor.temperature
        humidity = sensor.humidity
        return temperature, humidity
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return None, None

def validate_data(temperature, humidity):
    """Validates temperature and humidity readings."""
    if not -40 <= temperature <= 85:
        print(f"Invalid temperature reading: {temperature}")
        return False
    if not 0 <= humidity <= 100:
        print(f"Invalid humidity reading: {humidity}")
        return False
    return True

def main():
    """Main function to read and display temperature and humidity."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return  # Exit if I2C initialization failed

    sensor = initialize_sensor(i2c_bus)
    if sensor is None:
        return  # Exit if sensor initialization failed

    try:
        while True:
            temperature, humidity = read_sensor_data(sensor)

            if temperature is not None and humidity is not None:
                if validate_data(temperature, humidity):
                    timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
                    print(f"{timestamp} - Temperature: {temperature:.1f} C, Humidity: {humidity:.1f} %")

            time.sleep(RETRY_DELAY)

    except KeyboardInterrupt:
        print("Program shutting down.")

    except Exception as e:
        print(f"An unexpected error occurred: {e}")

    finally:
        # No need to explicitly close the I2C bus or sensor object
        # as they are automatically handled by their respective libraries.
        # The 'with' statement in the 'initialize_sensor' function
        # ensures proper resource cleanup when the 'finally' block is reached.
        i2c_bus.deinit() # Explicitly deinitialize the I2C bus

if __name__ == "__main__":
    main()

