#!/usr/bin/python

import time
import sys
import os

# MCP23017 I2C GPIO expander driver for Raspberry Pi
# (C) 2013 Narcisse Assogba <narcisse.assogba@gmail.com>
# Licensed under the GNU General Public License v2 or later

# This module provides a low-level driver for the MCP23017 I2C GPIO
# expander. It allows direct control of GPIO pins using a functional
# programming style.

import smbus
from contextlib import contextmanager

# Constants for the MCP23017 chip
MCP23017_ADDRESS = 0x20
MCP23017_PI_MODEL = 1
PI_MODEL = MCP23017_PI_MODEL

# Register addresses (grouped for clarity)
REGISTERS = {
    "GPA": {"OUT": 0x00, "CONFIG": 0x01, "VAL": 0x02},
    "GPB": {"OUT": 0x0C, "CONFIG": 0x0D, "VAL": 0x0E},
    "GPX": {"OUT": 0x18, "CONFIG": 0x19, "VAL": 0x1A},
    "GP_PUD": {"OUT": 0x20, "CONFIG": 0x21, "VAL": 0x22},
    "GP_ISR": {"OUT": 0x24, "CONFIG": 0x25, "VAL": 0x26},
    "BANK": {"OUT": 0x27, "CONFIG": 0x28, "VAL": 0x29},
}


@contextmanager
def mcp23017_device(bus_num, device_address):
    """Context manager for the MCP23017 device."""
    try:
        bus = smbus.SMBus(bus_num)
        yield bus
    finally:
        bus.close()  # Ensure bus is closed


def _check_device(bus, device_address, register, value, operation):
    """Helper function to check device health."""
    try:
        bus.read_byte_data(device_address, register)
        return True
    except Exception as e:
        print(f"Error accessing MCP23017 at address 0x{device_address:02X}: {e}")
        return False


def _write_register(bus, device_address, register, value):
    """Write a byte to the specified register."""
    try:
        bus.write_byte_data(device_address, register, value)
    except Exception as e:
        raise RuntimeError(f"Error writing to register 0x{register:02X}: {e}")



def _read_register(bus, device_address, register):
    """Read a byte from the specified register."""
    try:
        return bus.read_byte_data(device_address, register)
    except Exception as e:
        raise RuntimeError(f"Error reading from register 0x{register:02X}: {e}")



def _pud_up(value):
    return value | 0x04


def _pud_down(value):
    return value & 0xFB



def _isr_enabled(value):
    return value & 0x01 == 0x01


def _isr_disabled(value):
    return value & 0x01 == 0x00



@contextmanager
def gpio_group(bus_num, device_address, group_name):
    """Context manager for a GPIO group (GPA, GPB, GPX)."""
    if group_name not in REGISTERS:
        raise ValueError(f"Invalid GPIO group: {group_name}")

    group = REGISTERS[group_name]
    if not _check_device(bus, device_address, group["BANK"], 0x00, group["CONFIG"]):
        raise RuntimeError("MCP23017 device unresponsive.")

    try:
        yield group
    finally:

        if _isr_enabled(group["VAL"]): # Enable interrupts before setting outputs.
            _write_register(bus, device_address, group["GP_ISR"], 0x00)

        _write_register(bus, device_address, group["BANK"], 0x00) # Return to default bank



def setup_gpio(bus_num, device_address, group_name, pin, direction, pull_up_down=None):
    """Set up a single GPIO pin."""

    if group_name not in REGISTERS:
        raise ValueError(f"Invalid GPIO group: {group_name}")

    group = REGISTERS[group_name]
    if direction not in ("OUT", "IN"):
        raise ValueError("Invalid direction. Must be 'OUT' or 'IN'.")

    if pull_up_down not in ("UP", "DOWN"):
        raise ValueError("Invalid pull_up/down. Must be 'UP' or 'DOWN'.")


    value = 0
    if direction == "OUT":
        value = _pud_up(_pud_down(group["VAL"])) if pull_up_down == "DOWN" else _pud_down(_pud_up(group["VAL"]))
        _write_register(bus, device_address, group["OUT"], value)
    elif direction == "IN":
        value = _pud_up(_pud_down(group["VAL"])) if pull_up_down == "DOWN" else _pud_down(_pud_up(group["VAL"]))
        _write_register(bus, device_address, group["CONFIG"], value)

    _write_register(bus, device_address, group["VAL"], value)



def set_gpio(bus_num, device_address, group_name, pin, value):
    """Set the value of a single GPIO pin."""
    if group_name not in REGISTERS:
        raise ValueError(f"Invalid GPIO group: {group_name}")

    group = REGISTERS[group_name]
    value = 1 if value in ("ON", "True", "1") else 0 if value in ("OFF", "False", "0") else value #normalize value
    _write_register(bus, device_address, group["OUT"], value)


def get_gpio(bus_num, device_address, group_name, pin):
    """Get the value of a single GPIO pin."""
    if group_name not in REGISTERS:
        raise ValueError(f"Invalid GPIO group: {group_name}")

    group = REGISTERS[group_name]
    return _read_register(bus, device_address, group["VAL"])



def main():
    """Example usage."""
    group_name = "GPA" # Example: GPIO group A
    pin = 0 # Example: GPIO pin 0
    direction = "OUT" # Example: Set pin as output
    pull_up_down = "DOWN" # Example: Enable pull-down resistor


    with mcp23017_device(1, MCP23017_ADDRESS) as bus:
        with gpio_group(1, MCP23017_ADDRESS, group_name) as group:
            setup_gpio(bus, MCP23017_ADDRESS, group_name, pin, direction, pull_up_down)
            set_gpio(bus, MCP23017_ADDRESS, group_name, pin, "ON") # Example: Turn pin on
            print(f"Pin {pin} set to {get_gpio(bus, MCP23017_ADDRESS, group_name, pin)}")


if __name__ == "__main__":
    main()

