import sys
import threading
import RPi.GPIO as GPIO
import DOGProtocol as DOG  # Assuming this module exists

class DOGController:
    """
    Controls DOG device, handling communication and data logging.
    """

    def __init__(self, gpio_pin=9, log_file="data.log", poll_interval=0.1):
        """
        Initializes DOGController.

        Args:
            gpio_pin (int): GPIO pin for DOG device.
            log_file (str): Path to log file.
            poll_interval (float): Time between polls in seconds.
        """
        self.gpio_pin = gpio_pin
        self.log_file = log_file
        self.poll_interval = poll_interval
        self.stop_event = threading.Event()
        self.data_file = None  # Initialize data_file

        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.gpio_pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
            self.data_file = open(self.log_file, "a") # Open log file in append mode
            self.receive_thread = threading.Thread(target=self._receive_loop, daemon=True)
            self.receive_thread.start()
        except Exception as e:
            print(f"Error initializing: {e}")
            self.cleanup()
            sys.exit(1)


    def _receive_loop(self):
        """
        Continuously receives data from the DOG device and logs it.
        """
        while not self.stop_event.is_set():
            try:
                data = DOG.receive(self.gpio_pin)
                if data:  # Check if data is not empty/None
                    self._log_data(data)
            except Exception as e:
                print(f"Error receiving data: {e}")
            finally:
                threading.event.wait(self.poll_interval) # Use threading.event instead of self.stop_event.wait()


    def _log_data(self, data):
        """
        Logs received data to the log file.

        Args:
            data (str): Data to log.
        """
        try:
            self.data_file.write(data + "\n")
            self.data_file.flush()  # Ensure data is written immediately
        except Exception as e:
            print(f"Error writing to log file: {e}")



    def send_data(self, data):
        """
        Sends data via the DOG device.

        Args:
            data (str): Data to send.
        """
        try:
            DOG.send(self.gpio_pin, data)
        except Exception as e:
            print(f"Error sending data: {e}")



    def write_to_log(self, data):
        """
        Writes data directly to the log file.

        Args:
            data (str): Data to write.
        """
        try:
            self.data_file.write(data + "\n")
            self.data_file.flush()
        except Exception as e:
            print(f"Error writing to log file: {e}")




    def stop(self):
        """
        Stops the data reception thread and cleans up resources.
        """
        self.stop_event.set()
        self.receive_thread.join()
        self.cleanup()


    def cleanup(self):
        """
        Closes the GPIO and log file.
        """
        try:
            if self.data_file:
                self.data_file.close()
            GPIO.cleanup()
        except Exception as e:
            print(f"Error during cleanup: {e}")



def main():
    """
    Main function to run the DOG device controller.
    """

    def process_command(command, controller):
        """Processes operator commands."""
        args = command.split()
        if not args:
            return

        action = args[0].lower()

        if action == "help":
            if len(args) == 2 and args[1] in ("start", "stop", "display", "send", "write", "exit"):
                print(f"Usage: help <start|stop|display|send|write|exit>")
            else:
                print("Available commands: start, stop, display, send, write, exit")
        elif action == "start":
            if len(args) == 3 and args[2]:
                try:
                    controller.start(args[2])
                except Exception as e:
                    print(f"Error starting: {e}")
            else:
                print("Usage: start <log_file_path>")
        elif action == "stop":
            controller.stop()
        elif action == "display":
            try:
                with open(controller.log_file, "r") as file:
                    print(file.read())
            except FileNotFoundError:
                print(f"Log file not found: {controller.log_file}")
            except Exception as e:
                print(f"Error displaying log: {e}")
        elif action == "send":
            if len(args) == 3:
                controller.send_data(args[2])
            else:
                print("Usage: send <data>")
        elif action == "write":
            if len(args) == 3:
                controller.write_to_log(args[2])
            else:
                print("Usage: write <data>")
        elif action == "exit":
            sys.exit(0)
        else:
            print("Invalid command. Type 'help' for available commands.")


    if len(sys.argv) == 1:
        print("Available commands: start, stop, display, send, write, exit")
        sys.exit(1)

    controller = DOGController()

    try:
        while True:
            command = input("JAYES@ROVER53:\t")
            process_command(command, controller)
    except KeyboardInterrupt:
        print("\nKeyboardInterrupt")
        controller.stop()
        sys.exit(0)



if __name__ == "__main__":
    main()

