import requests
import time
import logging

# Configure logging for debugging and error tracking
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Define constants for GPIO pin and alert endpoint
VOLTAGE_SENSOR_PIN = 17  # BCM numbering
ALERT_ENDPOINT = 'http://example.com/alert'

# Setup GPIO using BCM numbering
GPIO.setmode(GPIO.BCM)

def setup_gpio(pin):
    """Sets up the GPIO pin with a pull-up resistor."""
    try:
        GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        logging.info(f"GPIO pin {pin} setup complete with pull-up resistor.")
    except Exception as e:
        logging.error(f"Error setting up GPIO pin {pin}: {e}")
        raise

def check_voltage_status(pin):
    """Reads the voltage sensor pin and returns True if voltage is present, False otherwise."""
    try:
        return GPIO.input(pin) == GPIO.LOW
    except Exception as e:
        logging.error(f"Error reading GPIO pin {pin}: {e}")
        return None

def send_power_failure_alert(url):
    """Sends an HTTP POST request to the alert endpoint with a power failure alert."""
    try:
        payload = {'alert': 'Power failure detected'}
        headers = {'Content-type': 'application/json'}
        response = requests.post(url, data=json.dumps(payload), headers=headers)
        response.raise_for_status()  # Raise HTTPError for bad responses (4xx or 5xx)
        logging.info(f"Alert sent successfully. Status code: {response.status_code}")
    except requests.exceptions.RequestException as e:
        logging.error(f"Error sending alert: {e}")

def main():
    """Main function to continuously monitor voltage status and send alerts."""
    try:
        setup_gpio(VOLTAGE_SENSOR_PIN)
        while True:
            voltage_detected = check_voltage_status(VOLTAGE_SENSOR_PIN)

            if voltage_detected:
                logging.info("Power is present")
            else:
                logging.warning("Power failure detected!")
                send_power_failure_alert(ALERT_ENDPOINT)

            time.sleep(1)  # Check every second

    except KeyboardInterrupt:
        logging.info("Program terminated by user.")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        GPIO.cleanup()  # Clean up GPIO on exit
        logging.info("GPIO cleanup completed.")

if __name__ == "__main__":
    import json  # Import json here to avoid unnecessary import if main is not executed
    main()

