#!/usr/bin/env python3

import RPi.GPIO as GPIO
import time
import signal
import sys

# Constants for GPIO pins (BCM numbering)
DATA_OUT_PIN = 5
TIMER_OUT_PIN = 6
DATA_IN_PIN = 20
TIMER_IN_PIN = 21

# Protocol signals
START_SIGNAL = [1, 0, 1, 1, 1, 1, 1, 1]
END_SIGNAL = [1, 1, 1, 1, 1, 1, 1, 1]
EMPTY_BUFFER = [0, 0, 0, 0, 0, 0, 0, 0]

# Timing settings
TRANSMIT_DELAY = 0.0005
RECEPTION_TIMEOUT = 1

# Global flag for graceful shutdown
shutdown_flag = False


def signal_handler(sig, frame):
    """Handles SIGINT and SIGTERM signals for graceful shutdown."""
    global shutdown_flag
    shutdown_flag = True
    print("Shutting down gracefully...")


def initialize_gpio():
    """Initializes GPIO pins and sets up exception handling."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)  # Suppress warnings
    except Exception as e:
        print(f"GPIO initialization error: {e}")
        sys.exit(1)


def char_to_bits(char):
    """Converts a character to a list of bits (0s and 1s)."""
    try:
        ascii_value = ord(char)
        bits = [0]  # Start with a 0
        for i in range(7):
            bits.append((ascii_value >> i) & 1)
        return bits
    except TypeError:
        print("Invalid character type. Must be a string.")
        return None


def bits_to_char(bits):
    """Converts a list of bits back to a character."""
    try:
        ascii_value = 0
        for i, bit in enumerate(bits[1:]):  # Skip the first bit (always 0)
            ascii_value |= bit << i
        return chr(ascii_value)
    except (TypeError, IndexError):
        print("Invalid bits format. Must be a list of 8 integers.")
        return None


def string_to_bits_list(message):
    """Converts a string to a list of bits."""
    return [bits_to_char(bits) for bits in message]


def bits_list_to_string(bits_list):
    """Converts a list of bits back to a string, ignoring start and end signals."""
    return "".join(bits_to_char(bits) for bits in bits_list if bits not in (START_SIGNAL, END_SIGNAL))


def transmit_bit(bit):
    """Transmits a single bit."""
    if bit:
        GPIO.output(DATA_OUT_PIN, GPIO.HIGH)
        GPIO.output(TIMER_OUT_PIN, GPIO.HIGH)
    else:
        GPIO.output(DATA_OUT_PIN, GPIO.LOW)
        GPIO.output(TIMER_OUT_PIN, GPIO.LOW)
    time.sleep(TRANSMIT_DELAY)
    GPIO.output(TIMER_OUT_PIN, GPIO.LOW)
    time.sleep(TRANSMIT_DELAY)


def send_data(message):
    """Sends a string over the data protocol."""
    try:
        initialize_gpio()
        GPIO.setup(DATA_OUT_PIN, GPIO.OUT, initial=GPIO.LOW)
        GPIO.setup(TIMER_OUT_PIN, GPIO.OUT, initial=GPIO.LOW)

        for bit in START_SIGNAL:
            transmit_bit(bit)

        for bit in message:
            for bit_ in char_to_bits(bit):
                transmit_bit(bit_)

        for bit in END_SIGNAL:
            transmit_bit(bit)

    except Exception as e:
        print(f"Transmission error: {e}")
    finally:
        GPIO.cleanup()  # Clean up GPIO in the finally block


def receive_data():
    """Receives data over the data protocol."""
    try:
        initialize_gpio()
        GPIO.setup(DATA_IN_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        GPIO.setup(TIMER_IN_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)

        received_bits = []
        current_bit = 0
        start_time = time.time()

        while not shutdown_flag:
            if GPIO.input(TIMER_IN_PIN) == GPIO.HIGH:
                current_bit = 1
                transmit_bit(0)  # Acknowledgement
                received_bits.append(current_bit)
                current_bit = 0
            else:
                if time.time() - start_time > RECEPTION_TIMEOUT:
                    raise TimeoutError("Reception timeout")
                if GPIO.input(DATA_IN_PIN) == GPIO.HIGH:
                    current_bit = 1
                else:
                    current_bit = 0

        return string_to_bits_list(received_bits)

    except Exception as e:
        print(f"Reception error: {e}")
        return []
    finally:
        GPIO.cleanup()


if __name__ == "__main__":
    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Example usage:
    try:
        send_data("Hello, world!")
        received_message = receive_data()
        print(f"Received: {bits_list_to_string(received_message)}")

    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        GPIO.cleanup()

