        GPIO.setup(self.error_pin, GPIO.OUT)
        GPIO.setup(self.zero_pin, GPIO.IN)

        # Create PWM instance for error pin.
        self.pwm_error = GPIO.PWM(self.error_pin, self.pwm_frequency)
        self.pwm_error.start(0.0)  # Start with 0% duty cycle

        self.last_message = time.time()
        self.subscriptions = {}

        # Worker classes for PID calculations.
        self.k10cr1 = WK10CR1()
        self.dac8532 = WDAC8532()

    def handle_message(self, message: str):
        """Processes a received message and updates PID calculations."""
        self.last_message = time.time()

        try:
            stream_filter, data_str = message.split(" ", 1)
            data = json.loads(data_str)

            if stream_filter in self.subscriptions:
                for subscription in self.subscriptions[stream_filter]:
                    result = self.k10cr1.process(data)
                    if result is not None:
                        self.dac8532.process(result)

        except (ValueError, json.JSONDecodeError) as e:
            self.logger.error(f"Error processing message: {e}.  Message was: {message}")
        except Exception as e:
            self.logger.exception(f"Error during message processing: {e}")


    def update_subscriptions(self, subscriptions: Dict[str, List[Dict[str, Any]]]):
        """Updates the subscriptions dictionary."""
        self.subscriptions = subscriptions

    def get_monitor_info(self) -> Dict[str, Any]:
        """Returns monitor information for the ZeroMQ watchdog."""
        return {
            "class_name": self.__class__.__name__,
            "control_state": self.pwm_error.duty_cycle,
            "last_message": time.time(),
            "subscriptions": self.subscriptions,
