# Authenticates users against a fingerprint database on a Raspberry Pi 5.

import time
import board
import busio
import adafruit_fingerprint

# Define GPIO pins for I2C communication with the fingerprint sensor.
I2C_SCL_PIN = board.SCL
I2C_SDA_PIN = board.SDA

def initialize_i2c():
    """Initializes the I2C bus."""
    try:
        i2c_bus = busio.I2C(I2C_SCL_PIN, I2C_SDA_PIN)
        return i2c_bus
    except ValueError as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_fingerprint_sensor(i2c_bus):
    """Initializes the fingerprint sensor."""
    try:
        fingerprint_sensor = adafruit_fingerprint.Adafruit_Fingerprint(i2c_bus)
        return fingerprint_sensor
    except RuntimeError as e:
        print(f"Error initializing fingerprint sensor: {e}")
        return None

def get_fingerprint_data(fingerprint_sensor):
    """Acquires and processes fingerprint data from the sensor."""
    print('Waiting for finger...')
    try:
        while fingerprint_sensor.get_image() != adafruit_fingerprint.OK:
            pass
        print('Templating...')
        if fingerprint_sensor.image_2_tz(1) != adafruit_fingerprint.OK:
            return None
        print('Searching...')
        if fingerprint_sensor.finger_search() != adafruit_fingerprint.OK:
            return None
        return fingerprint_sensor.get_model()
    except Exception as e:
        print(f"Error processing fingerprint data: {e}")
        return None

def authenticate_user(fingerprint_sensor, fingerprint_data):
    """Authenticates the user based on the fingerprint data."""
    try:
        if fingerprint_sensor.finger_search(fingerprint_data) != adafruit_fingerprint.OK:
            return False
        return True
    except Exception as e:
        print(f"Error authenticating user: {e}")
        return False

def main():
    """Main function to run the fingerprint access control system."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    fingerprint_sensor = initialize_fingerprint_sensor(i2c_bus)
    if fingerprint_sensor is None:
        return

    try:
        while True:
            fingerprint_data = get_fingerprint_data(fingerprint_sensor)
            if fingerprint_data:
                if authenticate_user(fingerprint_sensor, fingerprint_data):
                    print(f'Access Granted: ID={fingerprint_data}, Confidence={fingerprint_sensor.confidence}')
                else:
                    print('Access Denied')
            time.sleep(1)
    except KeyboardInterrupt:
        print("\nExiting program.")
    finally:
        i2c_bus.deinit()
        print("I2C bus deinitialized.")

if __name__ == "__main__":
    main()

