# Raspberry Pi ambient light sensor to LED brightness controller

import time
import board
import busio
import adafruit_tsl2561
import RPi.GPIO as GPIO

# Define GPIO pin for the LED
LED_GPIO_PIN = 18

# PWM frequency for the LED
PWM_FREQUENCY = 1000

def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return i2c_bus
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_light_sensor(i2c_bus):
    """Initialize the TSL2561 light sensor."""
    try:
        sensor = adafruit_tsl2561.TSL2561(i2c_bus)
        sensor.gain = adafruit_tsl2561.GAIN_MED
        return sensor
    except Exception as e:
        print(f"Error initializing light sensor: {e}")
        return None

def initialize_gpio(led_pin):
    """Initialize GPIO for LED control."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(led_pin, GPIO.OUT)
        pwm_led = GPIO.PWM(led_pin, PWM_FREQUENCY)
        pwm_led.start(0)
        return pwm_led
    except Exception as e:
        print(f"Error initializing GPIO: {e}")
        return None

def read_light_level(sensor):
    """Read the ambient light level from the sensor."""
    try:
        return sensor.lux
    except Exception as e:
        print(f"Error reading light level: {e}")
        return None

def adjust_led_brightness(pwm_led, light_level):
    """Adjust the LED brightness based on the light level."""
    if light_level is not None:
        try:
            duty_cycle = min(100, max(0, light_level / 10))
            pwm_led.ChangeDutyCycle(duty_cycle)
            print(f"Light Level: {light_level:.2f} lux, LED Duty Cycle: {duty_cycle:.2f}%")
        except Exception as e:
            print(f"Error adjusting brightness: {e}")

def cleanup_resources(pwm_led, i2c_bus):
    """Clean up GPIO and I2C resources."""
    try:
        if pwm_led:
            pwm_led.stop()
        GPIO.cleanup()
        if i2c_bus:
            i2c_bus.deinit()
        print("Resources cleaned up.")
    except Exception as e:
        print(f"Error during cleanup: {e}")

def main():
    """Main function to control LED brightness based on ambient light."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    light_sensor = initialize_light_sensor(i2c_bus)
    if light_sensor is None:
        cleanup_resources(None, i2c_bus)
        return

    pwm_led = initialize_gpio(LED_GPIO_PIN)
    if pwm_led is None:
        cleanup_resources(None, i2c_bus)
        return

    try:
        while True:
            light_level = read_light_level(light_sensor)
            if light_level is None:
                print("Warning: Failed to read light level. Setting LED to off.")
                adjust_led_brightness(pwm_led, 0)
            else:
                adjust_led_brightness(pwm_led, light_level)
            time.sleep(1)
    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        cleanup_resources(pwm_led, i2c_bus)

if __name__ == "__main__":
    main()

