#!/usr/bin/env python3

"""
Reads ambient luminance from a BH1750FVI light sensor connected to the Raspberry Pi
via I2C. Uses a functional approach with error handling and resource management.
"""

import time
import smbus2
from functools import partial
from typing import Tuple, Callable

# Constants
DEFAULT_I2C_ADDRESS = 0x23
MEASUREMENT_MODE = 0x10
CONTINUOUS_HIGH_RES = 0x10

# I2C bus initialization and cleanup functions
def initialize_i2c_bus(bus_number: int) -> smbus2.SMBus:
    """Initializes the I2C bus."""
    try:
        bus = smbus2.SMBus(bus_number)
        return bus
    except OSError as e:
        raise RuntimeError(f"Failed to initialize I2C bus {bus_number}: {e}")


def close_i2c_bus(bus: smbus2.SMBus) -> None:
    """Closes the I2C bus."""
    try:
        bus.close()
    except Exception as e:
        print(f"Error closing I2C bus: {e}")  # Non-fatal error


# Light sensor functionality
def check_sensor_address(bus: smbus2.SMBus, address: int) -> bool:
    """Checks if the sensor responds at the given address."""
    try:
        bus.read_byte(address)
        return True
    except OSError:
        return False


def read_luminance_data(bus: smbus2.SMBus, address: int) -> int:
    """Reads raw luminance data from the sensor."""
    try:
        data = bus.read_i2c_block_data(address, MEASUREMENT_MODE, 2)
        return (data[0] << 8) | data[1]
    except OSError as e:
        raise RuntimeError(f"Failed to read luminance data: {e}")


def calculate_luminance(raw_data: int) -> float:
    """Converts raw data to luminance in lux."""
    return raw_data / 1.2


def read_luminance(bus: smbus2.SMBus, address: int) -> float:
    """Reads and returns the luminance in lux."""
    raw_data = read_luminance_data(bus, address)
    return calculate_luminance(raw_data)


# Error handling and recovery
def handle_sensor_not_found(address: int) -> None:
    """Handles the case where the sensor is not found."""
    print(f"Error: Light sensor not found at address 0x{address:02X}")


def handle_read_error(error_message: str) -> None:
    """Handles I2C read errors by backing off and retrying."""
    print(f"Error reading light sensor data: {error_message}")
    time.sleep(1)


# Main program logic
def main_loop(bus: smbus2.SMBus, address: int, read_function: Callable[[smbus2.SMBus, int], float]) -> None:
    """Continuously reads and prints luminance."""
    try:
        while True:
            try:
                lux = read_function(bus, address)
                print(f"Ambient Light: {lux:.2f} lux")
                time.sleep(1)
            except RuntimeError as e:
                handle_read_error(e)
            except Exception as e:
                print(f"An unexpected error occurred: {e}")
                break  # Exit the loop on unexpected errors
    except KeyboardInterrupt:
        print("\nExiting light sensor monitor.")


def monitor_light_sensor(i2c_bus_number: int, sensor_address: int = DEFAULT_I2C_ADDRESS) -> None:
    """Monitors the light sensor with robust error handling and resource management."""
    try:
        bus = initialize_i2c_bus(i2c_bus_number)

        if not check_sensor_address(bus, sensor_address):
            handle_sensor_not_found(sensor_address)
            close_i2c_bus(bus)
            return

        read_light_sensor = partial(read_luminance, bus, sensor_address)  # Partial application
        main_loop(bus, sensor_address, read_light_sensor)

    finally:
        close_i2c_bus(bus)


if __name__ == "__main__":
    monitor_light_sensor(1)  # Use I2C bus 1 on Raspberry Pi

