    try:
        GPIO.output(pin, GPIO.HIGH)  # Turn LED on
        time.sleep(interval)
        GPIO.output(pin, GPIO.LOW)  # Turn LED off
        time.sleep(interval)
    except Exception as e:
        print(f"Error blinking LED: {e}")


def main():
    """Main function to control the LED blinking."""
    if not initialize_gpio():
        print("GPIO initialization failed. Exiting.")
        return

    print(f"Starting LED blink on GPIO {LED_PIN} with interval {BLINK_INTERVAL}s")

    try:
        while True:
            blink_led(LED_PIN, BLINK_INTERVAL)
    except KeyboardInterrupt:
        print("Program terminated by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        GPIO.output(LED_PIN, GPIO.LOW)  # Ensure LED is off on exit
        GPIO.cleanup()  # Release GPIO resources
        print("GPIO cleanup completed.")


