#!/usr/bin/python
import time
import atexit
import logging

try:
    import smbus
except ImportError:
    logging.warning("smbus not found.  Fake smbus will be used.")
    smbus = None  # Set smbus to None to indicate it's not available

from Adafruit_PWM_Servo_Driver import PWM

# Create logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
SERVO_MIN = 150  # Min pulse length out of 4096
SERVO_MAX = 600  # Max pulse length out of 4096
PWM_FREQUENCY = 60  # Standard PWM frequency for servos

# Servo channel assignments
CHANNEL_BASE = 0  # Base rotation
CHANNEL_DROP = 1  # Drop mechanism
CHANNEL_SEEK = 2  # Seek mechanism
CHANNEL_GRAB = 4  # Grabber

# Initialize I2C bus
try:
    if smbus is None:
        raise OSError("smbus not available. Cannot initialize I2C.")
    bus = smbus.SMBus(1)  # Rev 2 Pi, Rev 1 is bus 0
except OSError as e:
    logging.error(f"Failed to initialize I2C bus: {e}")
    raise

# Initialize PWM servo driver
try:
    pwm = PWM(bus, 0x40)  # Default address for PCA9685
    pwm.setPWMFreq(PWM_FREQUENCY)
    logging.info("PCA9685 PWM driver initialized successfully.")
except Exception as e:
    logging.error(f"Failed to initialize PCA9685: {e}")
    raise


def _calculate_pulse(angle):
    """Calculates the PWM pulse length for a given angle."""
    zero_pulse = (SERVO_MIN + SERVO_MAX) / 2
    pulse_width = zero_pulse - SERVO_MIN
    pulse = zero_pulse + (pulse_width * angle / 180)
    return int(pulse)


def move_servo(channel, target_angle, step_size=5, delay=0.04):
    """Moves a servo to a target angle with small steps and delay."""
    try:
        current_angle = pwm.getPWM(channel)
        if current_angle is None:
            current_angle = 0

        while abs(current_angle - target_angle) > step_size:
            if current_angle < target_angle:
                current_angle += step_size
            else:
                current_angle -= step_size

            pwm.setPWM(channel, 0, _calculate_pulse(current_angle))
            time.sleep(delay)

        pwm.setPWM(channel, 0, _calculate_pulse(target_angle))
        logging.debug(f"Servo {channel} moved to angle {target_angle}")

    except Exception as e:
        logging.error(f"Error moving servo {channel} to {target_angle}: {e}")


def seek(angle):
    """Moves the seek mechanism to a specified angle."""
    move_servo(CHANNEL_SEEK, angle)


def deseek(angle):
    """Moves the seek mechanism back to the default position."""
    move_servo(CHANNEL_SEEK, 90)


def drop(angle):
    """Lowers the drop mechanism to release an object."""
    move_servo(CHANNEL_DROP, angle)


def pick(angle):
    """Raises the pick mechanism to grab an object."""
    move_servo(CHANNEL_PICK, angle)


def grab(angle):
    """Closes the gripper to hold an object."""
    move_servo(CHANNEL_GRAB, angle)


def release(angle):
    """Opens the gripper to release an object."""
    move_servo(CHANNEL_GRAB, angle)


def move_base(angle):
    """Moves the base left or right."""
    move_servo(CHANNEL_BASE, angle)


def get_pos_x(x_center):
    """Calculates the base angle based on object's x-coordinate."""
    if x_center < 160:
        base_angle = 90
    elif x_center < 320:
        base_angle = 67
    elif x_center < 480:
        base_angle = 45
    elif x_center < 640:
        base_angle = 22
    else:
        base_angle = 0
    return base_angle


def get_pos_y(y_center):
    """Calculates the base angle based on object's y-coordinate."""
    if y_center < 120:
        base_angle = 22
    elif y_center < 240:
        base_angle = 45
    elif y_center < 360:
        base_angle = 67
    elif y_center < 480:
        base_angle = 90
    else:
        base_angle = 0
    return base_angle


def collect_object_steps(seek_angle):
    """Performs the sequence of actions to collect an object."""
    try:
        seek(seek_angle)
        pick(160)
        drop(100)
        grab(90)
        deseek(90)
        release(120)
        drop(160)
        pick(100)
    except Exception as e:
        logging.error(f"Error during collect_object_steps: {e}")
        raise


def drop_object_steps(drop_angle):
    """Performs the sequence of actions to drop an object."""
    try:
        drop(drop_angle)
        release(120)
        pick(100)
        deseek(90)
    except Exception as e:
        logging.error(f"Error during drop_object_steps: {e}")
        raise


def cleanup():
    """Releases all servos and closes the gripper."""
    try:
        for channel in range(16):
            pwm.setPWM(channel, 0, 0)
        release(120)  # Ensure gripper is open
        logging.info("Servos released and gripper opened in cleanup.")
    except Exception as e:
        logging.error(f"Error during cleanup: {e}")


# Register cleanup function to be called on exit
atexit.register(cleanup)


def collect_object(x_center, y_center, drop_angle):
    """Collects an object based on its coordinates."""
    try:
        pos_x = get_pos_x(x_center)
        pos_y = get_pos_y(y_center)

        move_base(pos_x)
        collect_object_steps(pos_y)
        move_base(90)  # Return to default base position
        drop_object_steps(drop_angle)

    except Exception as e:
        logging.error(f"Error during collect_object: {e}")
        raise


if __name__ == '__main__':
    try:
        # Example usage (replace with your specific logic)
        collect_object(240, 180, 135)

    except KeyboardInterrupt:
        logging.info("Program interrupted by user.")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        cleanup()

