#!/usr/bin/python3
# -*- coding: utf-8 -*-

"""
DS1338 Real-Time Clock Driver for Raspberry Pi.

This module provides a robust and efficient interface for interacting with the
DS1338 RTC chip via I2C. It offers comprehensive error handling, detailed
documentation, and adheres to best practices for hardware interaction.

Key Features:
- Comprehensive error handling and recovery.
- Detailed documentation using Python's docstring conventions.
- Best practices for hardware interaction (resource management, safe modes).
- Optimized for performance and robustness.
- Modular and maintainable code.
"""

import smbus
from datetime import datetime, timedelta
import logging

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class DS1338Error(Exception):
    """Base class for DS1338-specific exceptions."""
    pass


class DS1338CommunicationError(DS1338Error):
    """Raised when I2C communication fails."""
    pass


class DS1338InitializationError(DS1338Error):
    """Raised when DS1338 initialization fails."""
    pass


class DS1338DataError(DS1338Error):
    """Raised when invalid data is encountered."""
pass


class DS1338:
    """DS1338 Real-Time Clock Driver."""

    _REG_SECONDS = 0x00
    _REG_MINUTES = 0x01
    _REG_HOURS = 0x02
    _REG_DAY = 0x03
    _REG_DATE = 0x04
    _REG_MONTH = 0x05
    _REG_YEAR = 0x06
    _REG_CONTROL = 0x07
    _REG_STATUS = 0x0F  # Added Status Register address


    def __init__(self, twi=1, addr=0x68, retry_attempts=3):
        self._bus = smbus.SMBus(twi)
        self._addr = addr
        self._retry_attempts = retry_attempts
        self._initialize()


    def _initialize(self):
        """Initializes the DS1338 and verifies communication."""
        try:
            for attempt in range(self._retry_attempts):
                try:
                    # Test communication by reading the seconds register
                    self.read_register(self._REG_SECONDS)
                    logger.info("DS1338 initialized successfully.")
                    return  # Exit if initialization is successful
                except DS1338CommunicationError as e:
                    logger.warning(f"Attempt {attempt+1}/{self._retry_attempts} to initialize DS1338 failed: {e}")
                    if attempt == self._retry_attempts - 1:
                        raise DS1338InitializationError("Failed to initialize DS1338 after multiple attempts.") from e
            logger.info("DS1338 initialized successfully (initialization retry mechanism).")

        except DS1338CommunicationError as e:
            raise DS1338InitializationError("Failed to communicate with DS1338 during initialization.") from e


    def _write_register(self, register, data):
        """Writes data to a specific register with retry mechanism."""
        for attempt in range(self._retry_attempts):
            try:
                self._bus.write_byte_data(self._addr, register, data)
                return
            except IOError as e:
                logger.warning(f"I2C write error (attempt {attempt+1}/{self._retry_attempts}): {e}")
                if attempt == self._retry_attempts - 1:
                    raise DS1338CommunicationError("Failed to write to DS1338 after multiple attempts.") from e


    def _read_register(self, register):
        """Reads data from a specific register with retry mechanism."""
        for attempt in range(self._retry_attempts):
            try:
                return self._bus.read_byte_data(self._addr, register)
            except IOError as e:
                logger.warning(f"I2C read error (attempt {attempt+1}/{self._retry_attempts}): {e}")
                if attempt == self._retry_attempts - 1:
                    raise DS1338CommunicationError("Failed to read from DS1338 after multiple attempts.") from e


    def _bcd_to_int(self, bcd):
        """Converts BCD to integer."""
        try:
            return (bcd >> 4) * 10 + (bcd & 0x0F)
        except TypeError as e:
            raise DS1338DataError("Invalid BCD value provided.") from e


    def _int_to_bcd(self, integer):
        """Converts integer to BCD."""
        if not 0 <= integer <= 99:
            raise DS1338DataError("Integer value must be between 0 and 99.")
        return (integer // 10 << 4) | (integer % 10)


    def _validate_range(self, register, min_value, max_value):
        """Validates a value against the specified range."""
        try:
            current_value = self.read_register(register)
            if not min_value <= current_value <= max_value:
                raise DS1338DataError(f"Invalid value in register {register}: {current_value} outside of allowed range ({min_value}-{max_value}).")
        except DS1338CommunicationError as e:
            raise DS1338DataError(f"Failed to read register {register} for range validation: {e}") from e


    def read_all(self):
        """Reads all time and date registers."""
        try:
            self._validate_range(self._REG_SECONDS, 0, 59)
            self._validate_range(self._REG_MINUTES, 0, 59)
            self._validate_range(self._REG_HOURS, 0, 23)  # Assuming 24-hour format
            self._validate_range(self._REG_DAY, 1, 7)
            self._validate_range(self._REG_DATE, 1, 31)
            self._validate_range(self._REG_MONTH, 1, 12)
            self._validate_range(self._REG_YEAR, 0, 99)  # Year in the current century

            year = self._int_to_bcd(2000 + self.read_register(self._REG_YEAR))
            month = self._int_to_bcd(self.read_register(self._REG_MONTH))
            date = self._int_to_bcd(self.read_register(self._REG_DATE))
            day = self._int_to_bcd(self.read_register(self._REG_DAY))
            hours = self._int_to_bcd(self.read_register(self._REG_HOURS))
            minutes = self._int_to_bcd(self.read_register(self._REG_MINUTES))
            seconds = self._int_to_bcd(self.read_register(self._REG_SECONDS))

            return seconds, minutes, hours, day, date, month, year

        except DS1338DataError as e:
            raise  # Re-raise data validation errors


    def read_datetime(self, century=21):
        """Reads the date and time and returns a datetime object."""
        try:
            seconds, minutes, hours, day, date, month, year = self.read_all()
            year = self._int_to_bcd(century * 100 + year) # Construct the full year
            return datetime(1900 + century, month, date, hours, minutes, seconds)

        except (DS1338CommunicationError, ValueError, OverflowError) as e: # Catch potential errors during datetime construction
            raise DS1338DataError(f"Failed to construct datetime object: {e}") from e



    def write_all(self, seconds=None, minutes=None, hours=None, day=None, date=None, month=None, year=None):
        """Writes time and date registers."""

        if seconds is not None:
            self._write_register(self._REG_SECONDS, self._bcd(seconds))
        if minutes is not None:
            self._write_register(self._REG_MINUTES, self._bcd(minutes))
        if hours is not None:
            self._write_register(self._REG_HOURS, self._bcd(hours)) # Ensure 24-hour format
        if day is not None:
            self._write_register(self._REG_DAY, self._bcd(day))
        if date is not None:
            self._write_register(self._REG_DATE, self._bcd(date))
        if month is not None:
            self._write_register(self._REG_MONTH, self._bcd(month))
        if year is not None:
            self._write_register(self._REG_YEAR, self._bcd(year % 100)) # Store only the last two digits


    def write_datetime(self, dt):
        """Writes a datetime object to the RTC."""
        try:
            self.write_all(
                seconds=self._bcd(dt.second),
                minutes=self._bcd(dt.minute),
                hours=self._bcd(dt.hour),  # Assuming 24-hour format
                day=self._bcd(dt.isoweekday()),
                date=self._bcd(dt.day),
                month=self._bcd(dt.month),
                year=self._bcd(dt.year % 100),
            )
        except (TypeError, DS1338DataError, OverflowError) as e: # Catch potential errors
            raise DS1338DataError(f"Failed to write datetime to RTC: {e}") from e


    def _bcd(self, n):
        """Convert integer to BCD."""
        return self._int_to_bcd(n)

    def _bcd_plus(self, bcd1, bcd2):
        """Add two BCD values."""
        return self._int_to_bcd(bcd1 + bcd2)


def main():
