    _REG_DATE = 0x04
    _REG_MONTH = 0x05
    _REG_YEAR = 0x06
    _REG_CONTROL = 0x07
    _REG_STATUS = 0x0F  # Added Status Register address


    def __init__(self, twi=1, addr=0x68, retry_attempts=3):
        self._bus = smbus.SMBus(twi)
        self._addr = addr
        self._retry_attempts = retry_attempts
        self._initialize()


    def _initialize(self):
        """Initializes the DS1338 and verifies communication."""
        try:
            for attempt in range(self._retry_attempts):
                try:
                    # Test communication by reading the seconds register
                    self.read_register(self._REG_SECONDS)
                    logger.info("DS1338 initialized successfully.")
                    return  # Exit if initialization is successful
                except DS1338CommunicationError as e:
                    logger.warning(f"Attempt {attempt+1}/{self._retry_attempts} to initialize DS1338 failed: {e}")
                    if attempt == self._retry_attempts - 1:
                        raise DS1338InitializationError("Failed to initialize DS1338 after multiple attempts.") from e
            logger.info("DS1338 initialized successfully (initialization retry mechanism).")

        except DS1338CommunicationError as e:
            raise DS1338InitializationError("Failed to communicate with DS1338 during initialization.") from e


    def _write_register(self, register, data):
        """Writes data to a specific register with retry mechanism."""
        for attempt in range(self._retry_attempts):
            try:
                self._bus.write_byte_data(self._addr, register, data)
                return
            except IOError as e:
                logger.warning(f"I2C write error (attempt {attempt+1}/{self._retry_attempts}): {e}")
                if attempt == self._retry_attempts - 1:
                    raise DS1338CommunicationError("Failed to write to DS1338 after multiple attempts.") from e


    def _read_register(self, register):
        """Reads data from a specific register with retry mechanism."""
        for attempt in range(self._retry_attempts):
            try:
                return self._bus.read_byte_data(self._addr, register)
            except IOError as e:
                logger.warning(f"I2C read error (attempt {attempt+1}/{self._retry_attempts}): {e}")
                if attempt == self._retry_attempts - 1:
                    raise DS1338CommunicationError("Failed to read from DS1338 after multiple attempts.") from e


    def _bcd_to_int(self, bcd):
        """Converts BCD to integer."""
        try:
            return (bcd >> 4) * 10 + (bcd & 0x0F)
        except TypeError as e:
            raise DS1338DataError("Invalid BCD value provided.") from e


    def _int_to_bcd(self, integer):
        """Converts integer to BCD."""
        if not 0 <= integer <= 99:
            raise DS1338DataError("Integer value must be between 0 and 99.")
        return (integer // 10 << 4) | (integer % 10)


    def _validate_range(self, register, min_value, max_value):
        """Validates a value against the specified range."""
        try:
            current_value = self.read_register(register)
            if not min_value <= current_value <= max_value:
                raise DS1338DataError(f"Invalid value in register {register}: {current_value} outside of allowed range ({min_value}-{max_value}).")
        except DS1338CommunicationError as e:
            raise DS1338DataError(f"Failed to read register {register} for range validation: {e}") from e


