            self._validate_range(self._REG_MINUTES, 0, 59)
            self._validate_range(self._REG_HOURS, 0, 23)  # Assuming 24-hour format
            self._validate_range(self._REG_DAY, 1, 7)
            self._validate_range(self._REG_DATE, 1, 31)
            self._validate_range(self._REG_MONTH, 1, 12)
            self._validate_range(self._REG_YEAR, 0, 99)  # Year in the current century

            year = self._int_to_bcd(2000 + self.read_register(self._REG_YEAR))
            month = self._int_to_bcd(self.read_register(self._REG_MONTH))
            date = self._int_to_bcd(self.read_register(self._REG_DATE))
            day = self._int_to_bcd(self.read_register(self._REG_DAY))
            hours = self._int_to_bcd(self.read_register(self._REG_HOURS))
            minutes = self._int_to_bcd(self.read_register(self._REG_MINUTES))
            seconds = self._int_to_bcd(self.read_register(self._REG_SECONDS))

            return seconds, minutes, hours, day, date, month, year

        except DS1338DataError as e:
            raise  # Re-raise data validation errors


    def read_datetime(self, century=21):
        """Reads the date and time and returns a datetime object."""
        try:
            seconds, minutes, hours, day, date, month, year = self.read_all()
            year = self._int_to_bcd(century * 100 + year) # Construct the full year
            return datetime(1900 + century, month, date, hours, minutes, seconds)

        except (DS1338CommunicationError, ValueError, OverflowError) as e: # Catch potential errors during datetime construction
            raise DS1338DataError(f"Failed to construct datetime object: {e}") from e



    def write_all(self, seconds=None, minutes=None, hours=None, day=None, date=None, month=None, year=None):
        """Writes time and date registers."""

        if seconds is not None:
            self._write_register(self._REG_SECONDS, self._bcd(seconds))
        if minutes is not None:
            self._write_register(self._REG_MINUTES, self._bcd(minutes))
        if hours is not None:
            self._write_register(self._REG_HOURS, self._bcd(hours)) # Ensure 24-hour format
        if day is not None:
            self._write_register(self._REG_DAY, self._bcd(day))
        if date is not None:
