# radiation_sensor_uart_event_driven.py
# Raspberry Pi radiation sensor monitoring script using UART and an event loop.
# Designed for a professional monitoring system.

import serial
import time
import RPi.GPIO as GPIO
import select
import sys

# Serial port configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1  # seconds

# GPIO pin for alert (BCM numbering)
ALERT_GPIO_PIN = 18

# Radiation threshold (µSv/h)
RADIATION_THRESHOLD = 50.0

# Global variable for serial port
serial_port = None


def initialize_serial():
    """Initializes the serial port."""
    global serial_port
    try:
        serial_port = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
        print(f"Serial port {SERIAL_PORT} initialized.")
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        sys.exit(1)


def initialize_gpio():
    """Initializes the GPIO pin for the alert."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(ALERT_GPIO_PIN, GPIO.OUT)
    GPIO.output(ALERT_GPIO_PIN, GPIO.LOW)  # Ensure the alert is initially off
    print(f"GPIO pin {ALERT_GPIO_PIN} initialized.")


def read_radiation_level():
    """Reads radiation level from the serial port."""
    try:
        if serial_port.in_waiting > 0:
            line = serial_port.readline().decode('ascii', errors='replace').strip()
            if line:
                try:
                    radiation_value = float(line)
                    return radiation_value
                except ValueError:
                    print(f"Invalid data received: {line}")
                    return None
            else:
                return None
        return None
    except serial.SerialException as e:
        print(f"Serial read error: {e}")
        return None


def set_alert_state(radiation_value):
    """Sets the alert state based on the radiation level."""
    if radiation_value is not None:
        if radiation_value > RADIATION_THRESHOLD:
            GPIO.output(ALERT_GPIO_PIN, GPIO.HIGH)  # Activate alert
            print("Alert activated!")
        else:
            GPIO.output(ALERT_GPIO_PIN, GPIO.LOW)  # Deactivate alert
            print("Alert deactivated.")


def main_loop():
    """Main event loop for reading and processing radiation data."""
